<script>
 import {onMount} from 'svelte';import {page} from '$app/stores';import {goto} from '$app/navigation';import {getProject,listDevices,listSites,attachProjectDevice,attachProjectSite,listProjectEnvironments,createProjectEnvironment,listDatabaseServers,attachProjectDatabaseServer,detachProjectDevice,detachProjectSite,detachProjectDatabaseServer} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';
 let project=null,devices=[],assigned=[],sites=[],sitesAvailable=[],environments=[],databaseServers=[],assignedDatabases=[];let loading=true;let selectedDevice='';let selectedSite='';let busy=false;let newEnvironment='';let selectedDatabase='';
 async function load(){const [p,d,all,e,db]=await Promise.all([getProject($page.params.id),listDevices(),listSites(),listProjectEnvironments($page.params.id),listDatabaseServers()]);if(!p.ok){notify(p.error||'Проект не найден','error');goto('/projects');return}project=p.data.project;assigned=p.data.devices||[];sites=p.data.sites||[];if(d.ok)devices=d.data.devices||[];if(all.ok)sitesAvailable=all.data.sites||[];if(e.ok)environments=e.data.environments||[];if(db.ok)databaseServers=db.data.servers||[];assignedDatabases=p.data.database_servers||[];loading=false}
 onMount(load);
 $: available=devices.filter(d=>!assigned.some(a=>a.id===d.id));
 $: availableDatabaseServers=databaseServers.filter(db=>!assignedDatabases.some(a=>a.id===db.id));
 async function addDevice(){if(!selectedDevice)return;busy=true;const r=await attachProjectDevice(project.id,Number(selectedDevice));busy=false;if(r.ok){notify('Устройство добавлено','success');selectedDevice='';await load()}else notify(r.error||'Не удалось добавить устройство','error')}
 async function addSite(){if(!selectedSite)return;const [did,sid]=selectedSite.split(':');busy=true;const r=await attachProjectSite(project.id,Number(did),sid);busy=false;if(r.ok){notify('Сайт добавлен','success');selectedSite='';await load()}else notify(r.error||'Не удалось добавить сайт','error')}
 async function addDatabase(){if(!selectedDatabase)return;busy=true;const r=await attachProjectDatabaseServer(project.id,Number(selectedDatabase));busy=false;if(r.ok){notify('Database server добавлен в проект','success');selectedDatabase='';await load()}else notify(r.error||'Не удалось добавить сервер БД','error')}
 async function addEnvironment(){const name=newEnvironment.trim();if(name.length<2)return;busy=true;const r=await createProjectEnvironment(project.id,name);busy=false;if(r.ok){notify('Окружение создано','success');newEnvironment='';await load()}else notify(r.error||'Не удалось создать окружение','error')}
 async function removeDevice(id){if(!confirm('Открепить устройство от проекта? Само устройство и его данные останутся без изменений.'))return;busy=true;const r=await detachProjectDevice(project.id,id);busy=false;if(r.ok){notify('Устройство откреплено','success');await load()}else notify(r.error||'Не удалось открепить устройство','error')}
 async function removeSite(deviceId,siteId){if(!confirm('Открепить сайт от проекта? Файлы и работа сайта не будут удалены.'))return;busy=true;const r=await detachProjectSite(project.id,deviceId,siteId);busy=false;if(r.ok){notify('Сайт откреплён','success');await load()}else notify(r.error||'Не удалось открепить сайт','error')}
 async function removeDatabase(id){if(!confirm('Открепить Database Server от проекта? Сервер и базы останутся без изменений.'))return;busy=true;const r=await detachProjectDatabaseServer(project.id,id);busy=false;if(r.ok){notify('Database Server откреплён','success');await load()}else notify(r.error||'Не удалось открепить сервер БД','error')}
</script>
{#if loading}<div class="empty">Загрузка…</div>{:else if project}
<div class="page-header"><div><button class="back" on:click={()=>goto('/projects')}>← Projects</button><h1 class="page-title">{project.name}</h1><p class="page-desc">{project.description||project.slug}</p></div></div>
<section class="panel environments-panel"><div class="section-head"><div><h2>Environments</h2><p>Production, Development и Staging внутри проекта</p></div><div class="add"><input class="input" bind:value={newEnvironment} maxlength="64" placeholder="Новое окружение"/><Button variant="primary" disabled={busy||newEnvironment.trim().length<2} on:click={addEnvironment}>Создать</Button></div></div>
<div class="environment-grid">{#each environments as env}<a class="environment-card" href={'/projects/'+project.id+'/environments/'+env.id}><div class="environment-top"><span class="environment-icon">▣</span>{#if env.is_protected}<span class="protected">Protected</span>{:else}<span class="environment-state">Environment</span>{/if}</div><strong>{env.name}</strong><small>{env.description||env.slug}</small><code>{env.slug}</code><span class="environment-open">Открыть окружение →</span></a>{/each}</div>
{#if !environments.length}<div class="empty compact">Окружения появятся после применения миграции базы данных.</div>{/if}</section>
<section class="panel"><div class="section-head"><div><h2>Devices</h2><p>Устройства, входящие в проект</p></div><div class="add"><select class="input" bind:value={selectedDevice}><option value="">Выбрать устройство</option>{#each available as d}<option value={d.id}>{d.hostname||d.device_id}</option>{/each}</select><Button variant="primary" disabled={!selectedDevice||busy} on:click={addDevice}>Добавить</Button></div></div>
{#if assigned.length}<div class="resource-list">{#each assigned as d}<div class="resource"><a class="resource-link" href={'/devices/'+d.id+'?project_id='+project.id}><span class="resource-icon">▣</span><span><strong>{d.hostname||d.device_id}</strong><small>{d.device_id}</small></span><span class="muted">Open →</span></a><Button size="sm" variant="danger" disabled={busy} on:click={()=>removeDevice(d.id)}>Открепить</Button></div>{/each}</div>{:else}<div class="empty compact">В проект ещё не добавлены устройства.</div>{/if}</section>
<section class="panel"><div class="section-head"><div><h2>Database Servers</h2><p>Серверы баз данных, подключённые к проекту</p></div><div class="add"><select class="input" bind:value={selectedDatabase}><option value="">Выбрать сервер БД</option>{#each availableDatabaseServers as db}<option value={db.id}>{db.name} · {db.engine}</option>{/each}</select><Button variant="primary" disabled={!selectedDatabase||busy} on:click={addDatabase}>Добавить</Button></div></div>
{#if assignedDatabases.length}<div class="resource-list">{#each assignedDatabases as db}<div class="resource"><a class="resource-link" href={'/databases?project_id='+project.id}><span class="resource-icon">DB</span><span><strong>{db.name}</strong><small>{db.engine} · Device #{db.device_id} · {db.status}</small></span><span class="muted">Open →</span></a><Button size="sm" variant="danger" disabled={busy} on:click={()=>removeDatabase(db.id)}>Открепить</Button></div>{/each}</div>{:else}<div class="empty compact">В проект ещё не добавлены Database Servers.</div>{/if}</section>
<section class="panel"><div class="section-head"><div><h2>Websites</h2><p>Сайты, сгруппированные в проекте</p></div><div class="add"><select class="input" bind:value={selectedSite}><option value="">Выбрать сайт</option>{#each sitesAvailable as item}<option value={item.device_id+':'+item.site.site_id}>{item.device_name||'Android host'} / {item.site.site_id}</option>{/each}</select><Button variant="primary" disabled={!selectedSite||busy} on:click={addSite}>Добавить</Button></div></div>
{#if sites.length}<div class="resource-list">{#each sites as s}<div class="resource"><a class="resource-link" href={'/sites/'+s.device_id+'/'+encodeURIComponent(s.site_id)+'?project_id='+project.id}><span class="resource-icon">◉</span><span><strong>{s.site_id}</strong><small>{s.device_name}</small></span><span class="muted">Open →</span></a><Button size="sm" variant="danger" disabled={busy} on:click={()=>removeSite(s.device_id,s.site_id)}>Открепить</Button></div>{/each}</div>{:else}<div class="empty compact">Сайты пока не добавлены.</div>{/if}</section>
{/if}
<style>
.environments-panel{margin-bottom:14px}.environment-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.environment-card{display:grid;text-decoration:none;color:inherit;gap:7px;padding:13px;border:1px solid #30343b;border-radius:8px;background:#141416}.environment-top{display:flex;justify-content:space-between;align-items:center}.environment-icon{width:28px;height:28px;display:grid;place-items:center;border-radius:7px;background:#27272a;color:#d4d4d8}.environment-open{font-size:9px;color:#a1a1aa;margin-top:4px}.environment-card strong{font-size:12px}.environment-card small,.environment-card code{font-size:9px;color:#a1a1aa}.protected{font-size:8px;color:#fbbf24}.environment-state{font-size:8px;color:#a1a1aa}.back{border:0;background:none;color:#a5b4fc;font-size:10px;margin-bottom:10px}.panel{background:#101727;border:1px solid #253149;border-radius:12px;padding:16px;margin-bottom:13px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:13px}.section-head h2{font-size:12px}.section-head p{font-size:9px;color:#64748b;margin-top:3px}.add{display:flex;gap:7px}.add select{min-width:180px}.resource-list{display:grid;gap:6px}.resource{display:flex;align-items:center;gap:10px;padding:9px;border:1px solid #253149;border-radius:8px}.resource-link{display:flex;align-items:center;gap:10px;min-width:0;flex:1;text-decoration:none;color:inherit}.resource-icon{width:27px;height:27px;display:grid;place-items:center;background:#1b2740;color:#a5b4fc;border-radius:7px}.resource span:nth-child(2){display:grid;gap:2px;flex:1}.resource strong{font-size:10px}.resource small,.muted{font-size:9px;color:#64748b}.empty.compact{padding:17px;font-size:10px}
@media(max-width:650px){.environment-grid{grid-template-columns:1fr}.section-head{align-items:stretch;flex-direction:column}.add select{min-width:0;flex:1}}
</style>